// Pick for YouTube — which Reel to upload as a Short this run. Pure rules, no AI.
//  - forced test post (yt_force_post_key): any READY/PUBLISHED post with a video, once, even if yt_enabled = 0;
//  - otherwise, when yt_enabled = 1: the oldest Reel already PUBLISHED on Instagram in the last 48h and not yet
//    on YouTube, while the New York daily cap (yt_max_per_day) allows it.
// 0 items = nothing to do.

const rows = $('Load Config').all().map(i => i.json ?? {});
const val = (key, def) => {
  const r = rows.find(x => x.key === key);
  if (!r) return def;
  if (typeof def === 'number') return Number.isFinite(Number(r.value_number)) && r.value_number !== null ? Number(r.value_number) : def;
  return (r.value_string ?? '').trim() || def;
};
const cfg = {
  enabled: val('yt_enabled', 0) ? 1 : 0,
  maxPerDay: val('yt_max_per_day', 2),
  privacy: ['public', 'unlisted', 'private'].includes(val('yt_privacy', 'private')) ? val('yt_privacy', 'private') : 'private',
  category: val('yt_category_id', '20'),
  force: val('yt_force_post_key', ''),
  chatId: val('telegram_chat_id', ''),
};

const tz = 'America/New_York';
const nowMs = Date.now();
const today = $now.setZone(tz).toFormat('yyyy-MM-dd');
const nyDate = iso => (iso ? DateTime.fromISO(String(iso)).setZone(tz).toFormat('yyyy-MM-dd') : '');
const ageH = iso => (nowMs - Date.parse(iso ?? '')) / 3.6e6;
const posts = $input.all().map(i => i.json ?? {}).filter(p => p.post_key && p.video_url);

let pick = null, reason = '';
if (cfg.force) {
  pick = posts.find(p => p.post_key === cfg.force && !p.yt_video_id && ['READY', 'PUBLISHED'].includes(p.status));
  reason = pick ? 'forced by yt_force_post_key' : '';
  if (!pick) console.log(`forced post ${cfg.force} not found or already on YouTube: clear yt_force_post_key`);
}
if (!pick && cfg.enabled) {
  const doneToday = posts.filter(p => p.yt_video_id && nyDate(p.yt_published_at) === today).length;
  if (doneToday >= cfg.maxPerDay) {
    console.log(`daily cap reached (${doneToday}/${cfg.maxPerDay})`);
  } else {
    const queue = posts
      .filter(p => p.status === 'PUBLISHED' && !p.yt_video_id && !p.yt_error && ageH(p.published_at) <= 48)
      .sort((a, b) => Date.parse(a.published_at) - Date.parse(b.published_at));
    pick = queue[0] ?? null;
    reason = pick ? `oldest of ${queue.length} published on Instagram, not yet on YouTube` : '';
  }
}
if (!pick) return [];

const clean = s => String(s ?? '').replace(/[<>]/g, '').replace(/\s+/g, ' ').trim();
const base = clean(pick.meme_caption || pick.hook || pick.title) || 'Streamer moment';
const creator = clean(pick.creator_name);
let title = creator && !base.toLowerCase().includes(creator.toLowerCase()) ? `${base} | ${creator}` : base;
title = title.slice(0, 100 - ' #shorts'.length) + ' #shorts';
const tags = String(pick.hashtags ?? '').split(/\s+/).filter(Boolean).slice(0, 12);
const description = [
  String(pick.caption ?? '').replace(/[<>]/g, '').trim(),
  '',
  'Daily viral streamer moments. Subscribe for more! #shorts',
].join('\n').slice(0, 4900);

return [{
  json: {
    post_key: pick.post_key, video_url: pick.video_url, creator_name: creator, reason,
    forced: reason.startsWith('forced'),
    title, description, tags: tags.join(','), privacy: cfg.privacy, category: cfg.category, chat_id: cfg.chatId,
  },
}];
